-- compare_xw.tsv: for each literal, how many rows of tx `xw <op> <literal>` keeps, the
-- sum of their id, and how many rows DuckDB cannot decide (the comparison raises a
-- conversion error: TRY gives NULL for a row whose xw is not NULL), for each of the six
-- comparison operators. The literal is the SQL text the test runs too (a folded bound is
-- written as the arithmetic), so the file holds DuckDB's reading of it. NULL rows are in
-- neither the kept rows nor their complement. Column xw is DECIMAL(38, 10) and holds +-10^27: any literal with more than 10 digits of scale overflows DECIMAL(38).
COPY (
SELECT * FROM (
  SELECT 0 AS n, 'xw' AS col, '0.0000000001' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xw < 0.0000000001)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw < 0.0000000001)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xw < 0.0000000001) IS NULL AND xw IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <= 0.0000000001)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <= 0.0000000001)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xw <= 0.0000000001) IS NULL AND xw IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xw > 0.0000000001)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw > 0.0000000001)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xw > 0.0000000001) IS NULL AND xw IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw >= 0.0000000001)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw >= 0.0000000001)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xw >= 0.0000000001) IS NULL AND xw IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xw = 0.0000000001)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw = 0.0000000001)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xw = 0.0000000001) IS NULL AND xw IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <> 0.0000000001)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <> 0.0000000001)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xw <> 0.0000000001) IS NULL AND xw IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 1 AS n, 'xw' AS col, '0.00000000005' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xw < 0.00000000005)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw < 0.00000000005)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xw < 0.00000000005) IS NULL AND xw IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <= 0.00000000005)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <= 0.00000000005)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xw <= 0.00000000005) IS NULL AND xw IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xw > 0.00000000005)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw > 0.00000000005)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xw > 0.00000000005) IS NULL AND xw IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw >= 0.00000000005)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw >= 0.00000000005)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xw >= 0.00000000005) IS NULL AND xw IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xw = 0.00000000005)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw = 0.00000000005)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xw = 0.00000000005) IS NULL AND xw IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <> 0.00000000005)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <> 0.00000000005)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xw <> 0.00000000005) IS NULL AND xw IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 2 AS n, 'xw' AS col, '0.0000000001000' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xw < 0.0000000001000)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw < 0.0000000001000)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xw < 0.0000000001000) IS NULL AND xw IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <= 0.0000000001000)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <= 0.0000000001000)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xw <= 0.0000000001000) IS NULL AND xw IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xw > 0.0000000001000)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw > 0.0000000001000)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xw > 0.0000000001000) IS NULL AND xw IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw >= 0.0000000001000)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw >= 0.0000000001000)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xw >= 0.0000000001000) IS NULL AND xw IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xw = 0.0000000001000)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw = 0.0000000001000)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xw = 0.0000000001000) IS NULL AND xw IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <> 0.0000000001000)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <> 0.0000000001000)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xw <> 0.0000000001000) IS NULL AND xw IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 3 AS n, 'xw' AS col, '1000000000000000000000000000' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xw < 1000000000000000000000000000)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw < 1000000000000000000000000000)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xw < 1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <= 1000000000000000000000000000)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <= 1000000000000000000000000000)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xw <= 1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xw > 1000000000000000000000000000)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw > 1000000000000000000000000000)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xw > 1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw >= 1000000000000000000000000000)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw >= 1000000000000000000000000000)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xw >= 1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xw = 1000000000000000000000000000)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw = 1000000000000000000000000000)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xw = 1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <> 1000000000000000000000000000)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <> 1000000000000000000000000000)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xw <> 1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 4 AS n, 'xw' AS col, '-1000000000000000000000000000' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xw < -1000000000000000000000000000)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw < -1000000000000000000000000000)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xw < -1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <= -1000000000000000000000000000)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <= -1000000000000000000000000000)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xw <= -1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xw > -1000000000000000000000000000)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw > -1000000000000000000000000000)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xw > -1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw >= -1000000000000000000000000000)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw >= -1000000000000000000000000000)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xw >= -1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xw = -1000000000000000000000000000)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw = -1000000000000000000000000000)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xw = -1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <> -1000000000000000000000000000)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <> -1000000000000000000000000000)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xw <> -1000000000000000000000000000) IS NULL AND xw IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 5 AS n, 'xw' AS col, '999999999999999999999999999.9999999999' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xw < 999999999999999999999999999.9999999999)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw < 999999999999999999999999999.9999999999)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xw < 999999999999999999999999999.9999999999) IS NULL AND xw IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <= 999999999999999999999999999.9999999999)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <= 999999999999999999999999999.9999999999)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xw <= 999999999999999999999999999.9999999999) IS NULL AND xw IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xw > 999999999999999999999999999.9999999999)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw > 999999999999999999999999999.9999999999)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xw > 999999999999999999999999999.9999999999) IS NULL AND xw IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw >= 999999999999999999999999999.9999999999)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw >= 999999999999999999999999999.9999999999)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xw >= 999999999999999999999999999.9999999999) IS NULL AND xw IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xw = 999999999999999999999999999.9999999999)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw = 999999999999999999999999999.9999999999)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xw = 999999999999999999999999999.9999999999) IS NULL AND xw IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <> 999999999999999999999999999.9999999999)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <> 999999999999999999999999999.9999999999)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xw <> 999999999999999999999999999.9999999999) IS NULL AND xw IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 6 AS n, 'xw' AS col, '0' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xw < 0)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw < 0)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xw < 0) IS NULL AND xw IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <= 0)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <= 0)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xw <= 0) IS NULL AND xw IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xw > 0)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw > 0)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xw > 0) IS NULL AND xw IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw >= 0)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw >= 0)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xw >= 0) IS NULL AND xw IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xw = 0)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw = 0)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xw = 0) IS NULL AND xw IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <> 0)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <> 0)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xw <> 0) IS NULL AND xw IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 7 AS n, 'xw' AS col, '1' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xw < 1)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw < 1)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xw < 1) IS NULL AND xw IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <= 1)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <= 1)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xw <= 1) IS NULL AND xw IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xw > 1)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw > 1)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xw > 1) IS NULL AND xw IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xw >= 1)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw >= 1)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xw >= 1) IS NULL AND xw IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xw = 1)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw = 1)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xw = 1) IS NULL AND xw IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xw <> 1)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xw <> 1)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xw <> 1) IS NULL AND xw IS NOT NULL) AS ne_e
) AS q ORDER BY n
) TO 'compare_xw.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
